-- level:1.6
INSERT INTO content_text (doc_id, revision, text, updated_at, updated_by) VALUES ('level:1.6', 1, '{"location":"Cổng Kiểm Soát · Trạm Thẩm Vấn","briefing":"[NHẬT KÝ HỆ THỐNG – TRẠM THẨM VẤN]\nMọi tín hiệu về Cổng Kiểm Soát đều phải qua trạm này. Trạm gửi câu hỏi qua kênh nhập, từng dòng một. Chương trình in ra thứ gì, trạm đọc thứ đó như câu trả lời.\nTrạm gửi hai dòng: một mã hỏi (dãy số), rồi tên ca trực. Câu trả lời gồm 3 dòng, đúng thứ tự, đúng từng ký tự. Luật ở ô Mục tiêu.\nMỗi lượt, trạm đổi mã hỏi. Câu trả lời phải dựng từ thứ trạm vừa gửi… không chép từ lượt trước.","task_steps":["Bấm CHẠY với mã có sẵn rồi đọc terminal. Mỗi lần gọi `input()` đọc một dòng trạm gửi, theo đúng thứ tự, và luôn trả về chữ (`str`), kể cả khi dòng đó trông như số.","Sửa để terminal in đúng 3 dòng ở ô Mục tiêu. Họ tên lấy từ dòng khóa, mã đáp tính từ mã hỏi, tên ca lấy từ dòng thứ hai trạm gửi.","Không in thêm gì. Lời nhắc viết trong `input(...)` cũng in ra, và trạm đọc nó như một phần câu trả lời. Không sửa 2 dòng khóa.","Xong khi cả 3 mục tiêu chuyển xanh. Dùng không quá 5 câu lệnh và vẫn trả lời đúng khi OMNI đổi câu hỏi thì được thêm sao."],"objectives":[{"line":1,"label":"DANH TINH:, một dấu cách, rồi họ tên trong hồ sơ"},{"line":2,"label":"MA DAP:, một dấu cách, rồi mã hỏi cộng số khu"},{"line":3,"label":"CA, tên ca trạm gửi, rồi DA DUYET (cách nhau một dấu cách)"}],"hints":["So dòng 7 với dòng 8. Cả hai đều có một cái tên nằm trong cặp ngoặc nhọn, nhưng chỉ một dòng có thêm một chữ đứng ngay trước dấu nháy. Rồi nhìn lại dòng 8: thứ trạm gửi qua kênh nhập luôn đến dưới dạng chữ… dù trông như số.","Mỗi lần đọc kênh nhập lấy đúng một dòng, theo thứ tự trạm gửi. Đọc hết những gì cần trước, đổi hình dạng thứ phải tính, rồi mới in.\n\nđọc  <dòng 1: mã hỏi>, đổi thành số\nđọc  <dòng 2: tên ca>\nin   DANH TINH: <họ tên trong hồ sơ>\nin   MA DAP: <mã hỏi cộng số khu>\nin   CA <tên ca> DA DUYET","Mảnh tài liệu Python còn đọc được:\nten = input()           → đọc một dòng, luôn là str\nso = int(input())       → đọc một dòng rồi đổi thành số nguyên\nlop = \"10A\"\nprint(f\"Lop {lop}\")     → Lop 10A\nprint(f\"{2 + 3} qua\")    → 5 qua      (trong ngoặc nhọn đặt được cả một phép tính)\nprint(\"Lop {lop}\")      → Lop {lop}  (thiếu f: ngoặc nhọn in nguyên văn)\ninput(\"Ten: \")          → in Ten: trước khi đọc, không xuống dòng; lời nhắc này cũng là đầu ra\nĐọc nhiều lần hơn số dòng được gửi → EOFError: EOF when reading a line"],"reactions":{"entry":"Trạm Thẩm Vấn. Trạm hỏi qua kênh nhập, từng dòng một… và đọc mọi thứ bạn in ra như câu trả lời. Chưa cần sửa gì. Chạy một lần.","output_missing":"Từ dòng trả lời thứ {out_line} trở đi, trạm không nhận được gì. Câu trả lời còn thiếu.","output_mismatch":"Dòng trả lời thứ {out_line} lệch ở ký tự thứ {col}. Trạm không đoán ý. Nó bác cả câu trả lời.","output_case_only":"Dòng trả lời thứ {out_line}: từng chữ cái đều đúng… nếu bỏ qua cỡ chữ. Trạm không bỏ qua.","output_extra":"Đủ dòng. Rồi thêm {count} dòng trạm không hỏi. Trạm bác cả lượt.","output_is_label":"Dòng trả lời thứ {out_line} chở nguyên tên một ô nhớ, cả cặp ngoặc bao quanh. Trạm cần thứ cất trong ô đó… không cần cái tên.","output_has_prompt":"Dòng trả lời thứ {out_line} chở theo lời nhắc chương trình tự in ra lúc chờ kênh nhập. Trạm không tách lời nhắc khỏi câu trả lời… chữ nào in ra cũng tới trạm.","EOFError":"Dòng {line}. Chương trình đứng chờ một câu hỏi… mà trạm không gửi. Đếm xem trạm gửi mấy dòng, và mã đọc kênh nhập mấy lần.","SyntaxError":"Dòng {line}. Trình dịch không đọc nổi câu này. Chương trình chưa chạy… trạm chưa nhận gì.","IndentationError":"Dòng {line}. Lề trái lệch. Với Python, khoảng trắng đầu dòng… là ngữ pháp.","TypeError":"Dòng {line}. TypeError. Thứ đến từ kênh nhập trông như số… nhưng không phải số. Hai hình dạng khác nhau vừa bị ghép vào một phép tính.","ValueError":"Dòng {line}. ValueError. Một dòng chữ bị đòi biến thành số. Xem lại thứ tự trạm gửi: dòng nào đến trước?","NameError":"Dòng {line}. NameError. Dòng này gọi một cái tên chưa từng có trong bộ nhớ. Soát từng ký tự.","ZeroDivisionError":"Dòng {line}. Chia cho không. Lõi từ chối.","AttributeError":"Dòng {line}. AttributeError. Thứ này không mang cái bạn đang gọi.","runtime_error":"Dòng {line}. {error_type}. Chương trình dừng giữa chừng. Những dòng sau nó chưa kịp tới trạm.","timeout":"Mã chạy quá lâu. Tôi cắt kết nối… trước khi trạm lần ra dấu.","resource_limit":"Bộ nhớ quá tải. Tôi cắt tiến trình… để laptop còn sống.","blocked_import":"Mô-đun đó bị phong tỏa. Ở Vùng Tối, ta chỉ có những gì đang cầm trong tay.","system_exit":"Chương trình tự dừng giữa chừng. Trạm không nhận được phần còn lại.","alert_exceeded":"Trạm duyệt. Nhưng {count} câu lệnh… mỗi câu là một xung trên dây. Sentinel đã ghi nhận. Viết gọn hơn.","counter_ValueError":"OMNI đổi câu hỏi. Dòng {line} vỡ: ValueError. Mã không chịu được bộ câu hỏi mới.","counter_error":"OMNI đổi câu hỏi. Dòng {line}: {error_type}. Mã không trụ nổi.","wrong_value_counter":"OMNI đổi câu hỏi. Dòng trả lời thứ {out_line} của bạn vẫn như cũ… nó trả lời một câu trạm không còn hỏi.","counter_timeout":"OMNI đổi câu hỏi. Mã của bạn treo trên bộ câu hỏi mới… Tôi cắt kết nối. Trạm chỉ duyệt một nửa.","two_stars":"Trạm duyệt. Không để lại dấu vết.","three_stars":"Trạm đổi câu hỏi. Câu trả lời vẫn đúng. …Tôi ghi nhận điều đó.","repeated_fail":"Cùng một lỗi, lần thứ {count}. Nhật ký gợi ý vẫn ở đây. Tôi chỉ hỏi được… không trả lời thay.","engine_error":"Lõi Python không phản hồi. Đang khởi động lại…","generic":"Có gì đó không khớp. Đọc lại từng dòng trạm nhận trong terminal."},"reaction_variants":{"output_mismatch":"Dòng trả lời thứ {out_line} vẫn lệch, từ ký tự thứ {col}. Đặt dòng cần và dòng nhận trong terminal cạnh nhau.","output_is_label":"Dòng trả lời thứ {out_line} vẫn chở tên ô nhớ. Trạm đọc đúng từng ký tự bạn gửi… và cái tên đó không phải câu trả lời.","TypeError":"Dòng {line}. Vẫn TypeError. Trạm gửi gì cũng đến dưới dạng chữ. Chữ không cộng được với số… phải đổi hình dạng trước khi tính."},"counter_attack_banner":"CẢNH BÁO: OMNI ĐỔI BỘ CÂU HỎI CỦA TRẠM","outro":"Trạm đóng dấu duyệt. Trong bộ nhớ trạm còn một bản ghi câu hỏi cũ, không thuộc bộ câu hỏi nào của OMNI:","lore_fragment":"KTS-01: Mỗi mảnh khóa bằng một câu hỏi. Máy chỉ kiểm được câu trả lời có đúng định dạng hay không… không kiểm được ai đang trả lời. Mảnh đầu tiên khóa dưới Cổng Kiểm Soát.","component":"Lời đáp xác thực","outro_beats":[{"kind":"echo","text":"Danh sách ca trực của trạm. Gói nào qua được trạm thì NX-0417 kiểm tay ở cổng."},{"kind":"kai","text":"Tôi sắp đứng trước mặt em mình. Bằng một cái tên không phải của tôi."},{"kind":"card","text":"TÍN HIỆU · 0xA7\n\"Đủ sáu thành phần. Tôi đang đợi ở Cổng Kiểm Soát.\""},{"kind":"echo","text":"Tín hiệu đó không đi qua Mạng Mù. Nó phát từ bên trong cổng."}],"knowledge_summary":{"title":"Đọc dữ liệu nhập: input() và f-string","sections":[{"heading":"`input()` đọc một dòng","body":"`input()` đọc một dòng từ dữ liệu nhập rồi trả về dòng đó. Kết quả luôn là chuỗi (`str`), kể cả khi dòng chỉ gồm chữ số."},{"heading":"Mỗi lần gọi đọc dòng kế tiếp","body":"Gọi `input()` hai lần thì đọc hai dòng, theo đúng thứ tự chúng đến. Cần dùng một dòng ở chỗ khác thì gán nó cho một biến ngay khi đọc."},{"heading":"Đổi sang số trước khi tính","body":"Chuỗi đọc được không cộng với số. Bọc `input()` trong `int()`, như ở bài 1.4, để có số nguyên ngay khi đọc: `int(input())`."},{"heading":"f-string đặt giá trị vào giữa chữ","body":"Viết chữ `f` ngay trước dấu nháy mở thì chuỗi thành f-string. Python tính mọi thứ trong cặp ngoặc nhọn `{...}` rồi đặt kết quả vào đúng chỗ đó. Trong ngoặc có thể là tên biến hoặc cả một biểu thức như `{so_qua + 2}`."},{"heading":"Thiếu `f` thì ngoặc nhọn chỉ là chữ","body":"Không có `f`, chuỗi in ra đúng như đã viết, cả cặp ngoặc nhọn lẫn tên bên trong. Python không báo lỗi, nên lỗi này chỉ lộ ra khi đọc kết quả."},{"heading":"Lời nhắc của `input()` cũng là đầu ra","body":"`input(\"Ten: \")` in lời nhắc `Ten: ` trước khi đọc, không xuống dòng. Ở terminal thật, chữ người dùng gõ hiện ngay sau lời nhắc. Khi dữ liệu nhập nạp sẵn như ở đây, không ai gõ gì, nên dòng in kế tiếp dính liền vào lời nhắc."}],"mistakes":[{"code":"ma = \"8210\"\nprint(ma + 7)","explain":"`ma` là chuỗi `\"8210\"`, còn `7` là số. Python không cộng chuỗi với số. Đổi trước rồi mới cộng: `int(ma) + 7`."},{"code":"ten = \"Lan\"\nprint(\"Chao {ten}\")","explain":"Thiếu `f` trước dấu nháy nên `{ten}` chỉ là chữ. Viết `print(f\"Chao {ten}\")` để in `Chao Lan`."},{"code":"a = input()\nb = input()","explain":"Dữ liệu nhập đã hết dòng mà chương trình vẫn gọi `input()`. Số lần gọi `input()` phải khớp với số dòng được gửi."},{"code":"so = int(input())","explain":"Dòng đọc được là `DEM`, không phải chữ số, nên `int()` không đổi được. Thường do đọc sai thứ tự: dòng chữ rơi vào chỗ đang chờ một con số."},{"code":"ma = input(\"Ma: \")\nprint(\"MA\", ma)","explain":"Với dòng nhập `8210`, lời nhắc `Ma: ` in ra trước, rồi `print` in tiếp trên cùng dòng. Khi kết quả được chấm từng ký tự, lời nhắc làm lệch cả dòng. Bỏ lời nhắc: `ma = input()`."}],"next":"Màn Boss: ghép mọi thứ của Chương 1 và vượt ba vòng quét liên tiếp."}}', '2026-10-27T18:32:49.279Z', 'migration') ON CONFLICT(doc_id) DO NOTHING;
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'level:1.6' AND revision = 1 AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;
